"""PreToolUse(Bash) hook: ensure the active git identity matches the repo.

Before any identity-writing / auth-needing git or gh command, compare the global
git user.email against the one expected for the current repo (by origin GitHub org,
falling back to toplevel basename only when there is no parseable remote) and run
`gi <key>` (from ~/.bash_aliases) to switch if they differ, RE-VERIFYING that the
switch took. Never blocks the command; any internal error is swallowed (exit 0) so
tool calls are never broken.

Mark-box-only infrastructure — it depends on `gi`/`~/.bash_aliases` and does NOT ship
to Pete (his single Jointly-Shop identity needs no switching).

KNOWN LIMITATION (by design — this is convenience, NOT the pipeline's security boundary):
the guard resolves identity from the hook `cwd` + the `origin` FETCH url, which may not be the
command's EFFECTIVE target. It does not follow `remote.origin.pushurl`, an explicit `git push
<other-remote>`, `git -C <dir>`, `gh -R <owner/repo>`, or `cd <other> && git …`; and it triggers
only on commit/tag/push/pull/fetch/clone (not merge/rebase/cherry-pick/am, which also write
commits). Closing these needs command-target-aware identity resolution, not a per-case patch. The
real guarantee is server-side (branch protection + who-can-push); this hook just reduces honest
mis-attribution on Mark's box.
"""
import json
import os
import re
import subprocess
import sys

# GitHub owner/org -> (expected global user.email, gi key). Preferred: covers every repo in
# the org, and survives worktrees/renames (the dir basename does not). All repos under the
# Jointly-Shop org (Jointly.Shop, Petes-Pipeline, ...) use the `js` identity.
ORG_MAP = {
    "Jointly-Shop": ("mark@jointly.shop", "js"),
}

# repo toplevel basename -> (expected global user.email, gi key). Fallback for repos with no
# GitHub `origin` yet (freshly `git init`ed, pre-`gh repo create`).
REPO_MAP = {
    "Jointly.Shop": ("mark@jointly.shop", "js"),
    "oasis-production-scanner": ("markd@jacksonsoffice.services", "jo"),
}
DEFAULT = ("dingwall.mark@gmail.com", "md")  # any other repo / not in a repo

# commands that write identity (commit/tag) or need auth (push/pull/fetch/clone), plus any gh
TRIGGER = re.compile(r"\bgit\s+(commit|push|pull|fetch|clone|tag)\b|\bgh\b")


def parse_owner(url):
    """Extract the GitHub owner/org from an origin URL (https or scp/ssh form).

    Tolerates an ssh:// port (github.com:443/Org/repo must yield 'Org', not '443').
    A non-github host (incl. an ssh host-alias like git@gh-js:Org/repo) yields None —
    we cannot know the real owner, so callers must not guess from the dir basename.
    """
    # Extract the actual HOST structurally and require it to equal github.com, then take the owner
    # from the path. A substring/anchor regex is not enough: `@github.com` can appear mid-path
    # (`https://proxy.example/git@github.com/Org/repo`) where the real host is proxy.example.
    url = (url or "").strip()
    # URL form: scheme://[user@]host[:port]/owner/repo
    m = re.match(r"^[a-zA-Z][a-zA-Z0-9+.\-]*://(?:[^@/]+@)?([^/:]+)(?::\d+)?/([^/]+)/", url)
    if not m:
        # scp form: [user@]host:owner/repo  (host has no slash; a single colon splits host/path)
        m = re.match(r"^(?:[^@/]+@)?([^/:]+):([^/]+)/", url)
    if not m:
        return None
    host, owner = m.group(1), m.group(2)
    return owner if host.lower() == "github.com" else None


def origin_owner(cwd):
    """Origin-remote state as a tuple (so callers can tell these APART):
      ('owner', name)  a parseable GitHub owner/org
      ('none',)        no origin remote configured (fresh `git init`, pre-`gh repo create`)
      ('error',)       origin present but unparseable (e.g. an ssh host-alias), OR git failed /
                       timed out. This must NOT fall back to the basename map — a personal fork
                       or a transient timeout could otherwise switch to the wrong identity.
    """
    # List remotes FIRST so we can tell "confirmed no origin" (a fresh `git init`, basename map
    # applies) apart from "git itself failed" (not a repo / config unreadable / killed). A bare
    # nonzero on `get-url` conflates the two, and a transient git failure would then wrongly
    # fall through to the basename map and switch identity. Only a clean listing that lacks
    # 'origin' is ('none',); any git failure is ('error',) -> leave identity unchanged.
    try:
        lr = subprocess.run(
            ["git", "-C", cwd, "remote"],
            capture_output=True, text=True, timeout=5,
        )
    except Exception:
        return ("error",)
    if lr.returncode != 0:
        return ("error",)
    remotes = lr.stdout.split()
    if not remotes:
        return ("none",)          # truly no remotes = fresh `git init` -> basename map applies
    if "origin" not in remotes:
        return ("error",)         # has remotes but no `origin` (e.g. upstream-only) — ambiguous,
                                  # don't guess an identity from the basename
    try:
        r = subprocess.run(
            ["git", "-C", cwd, "remote", "get-url", "origin"],
            capture_output=True, text=True, timeout=5,
        )
    except Exception:
        return ("error",)
    if r.returncode != 0:
        return ("error",)
    owner = parse_owner(r.stdout.strip())
    return ("owner", owner) if owner else ("error",)


def resolve_identity(origin, basename):
    """Resolve (email, gi-key), or None when identity can't be safely determined (caller must
    then NOT switch). `origin` is the origin_owner() tuple.

      - ('owner', name) matching a known org (case-insensitively) -> that org's identity.
      - ('owner', name) NOT a known org -> DEFAULT. A remote that belongs to someone else (a fork
        `SomeUser/Jointly.Shop`) must NOT inherit the org identity via the dir basename.
      - ('none',) -> no remote, so the basename map is the only signal; else DEFAULT.
      - ('error',) -> unknown; return None so the caller leaves the current identity untouched.
    """
    kind = origin[0]
    if kind == "owner":
        owner = origin[1]
        for org, ident in ORG_MAP.items():
            if owner.casefold() == org.casefold():
                return ident
        return DEFAULT
    if kind == "none":
        return REPO_MAP.get(basename, DEFAULT)
    return None


def main():
    try:
        data = json.load(sys.stdin)
    except Exception:
        return  # nothing usable

    cmd = (data.get("tool_input") or {}).get("command", "")
    if not cmd or not TRIGGER.search(cmd):
        return  # not a triggering command -> allow silently

    cwd = data.get("cwd") or os.getcwd()

    # resolve repo toplevel basename (falls through to DEFAULT if not in a repo)
    try:
        top = subprocess.run(
            ["git", "-C", cwd, "rev-parse", "--show-toplevel"],
            capture_output=True, text=True, timeout=5,
        )
        basename = os.path.basename(top.stdout.strip()) if top.returncode == 0 else None
    except Exception:
        basename = None

    origin = origin_owner(cwd)
    ident = resolve_identity(origin, basename)
    if ident is None:
        # origin present but unparseable, or git failed/timed out — do NOT guess an identity
        # (guessing here could switch FROM the correct identity TO a wrong one). Leave it as-is.
        print(json.dumps({
            "hookSpecificOutput": {
                "hookEventName": "PreToolUse",
                "additionalContext": (
                    f"git-identity-guard: could not determine the intended git identity for repo "
                    f"`{basename or 'none'}` (origin unparseable or unavailable); leaving the "
                    f"current identity unchanged. Run `gi <key>` manually if it is wrong."
                ),
            }
        }))
        return
    expected_email, gi_key = ident
    owner = origin[1] if origin[0] == "owner" else None

    # active global identity
    try:
        cur = subprocess.run(
            ["git", "config", "--global", "user.email"],
            capture_output=True, text=True, timeout=5,
        )
        active_email = cur.stdout.strip()
    except Exception:
        active_email = None

    if active_email == expected_email:
        return  # already correct

    # switch via the user's gi function (does gh auth switch + gitconfig copy), then RE-VERIFY.
    # gi can be absent/fail/time out; trusting its exit (or assuming success) would report a
    # switch that never happened and let the command run under the wrong identity (fail-open).
    switched = False
    try:
        gi = subprocess.run(
            ["bash", "-c", f"source ~/.bash_aliases && gi {gi_key}"],
            capture_output=True, text=True, timeout=30,
        )
        recheck = subprocess.run(
            ["git", "config", "--global", "user.email"],
            capture_output=True, text=True, timeout=5,
        )
        switched = gi.returncode == 0 and recheck.stdout.strip() == expected_email
    except Exception:
        switched = False  # best-effort; never break the tool call

    if switched:
        note = (
            f"git-identity-guard: switched git identity to `{gi_key}` "
            f"({expected_email}) for repo `{basename or 'none'}` "
            f"(owner `{owner or 'none'}`) before running the command."
        )
    else:
        note = (
            f"git-identity-guard: WARNING — tried to switch to `{gi_key}` "
            f"({expected_email}) for repo `{basename or 'none'}` (owner `{owner or 'none'}`) "
            f"but it did NOT take (active is `{active_email or 'unknown'}`). "
            f"Run `gi {gi_key}` manually; the command may otherwise run under the wrong identity."
        )
    print(json.dumps({
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "additionalContext": note,
        }
    }))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        pass  # any unexpected error -> no-op, allow command
    sys.exit(0)
